async (page) => {
  const input = page.locator('.new-todo');
  const results = {};
  // whitespace trimming
  await input.fill('   spaced todo   ');
  await input.press('Enter');
  results.afterWhitespaceAdd = await page.locator('[data-testid="todo-title"]').allTextContents();
  results.inputValueAfterAdd = await input.inputValue();
  // empty submit
  await input.fill('');
  await input.press('Enter');
  results.afterEmptySubmit = await page.locator('[data-testid="todo-item"]').count();
  // whitespace-only submit
  await input.fill('     ');
  await input.press('Enter');
  results.afterWhitespaceOnly = await page.locator('[data-testid="todo-item"]').count();
  results.inputValueAfterWsOnly = await input.inputValue();
  return results;
}

