async (page) => {
  const r = {};
  const items = page.locator('[data-testid="todo-item"]');
  // Filters
  await page.getByRole('link', { name: 'Active' }).click();
  r.activeUrl = page.url();
  r.activeTitles = await page.locator('[data-testid="todo-title"]').allTextContents();
  r.activeSelectedLink = await page.locator('.filters a.selected').textContent();
  r.activeCounter = await page.locator('[data-testid="todo-count"]').textContent();
  r.clearVisibleOnActive = await page.locator('.clear-completed').isVisible();
  await page.getByRole('link', { name: 'Completed' }).click();
  r.completedUrl = page.url();
  r.completedTitles = await page.locator('[data-testid="todo-title"]').allTextContents();
  // toggle-all state on completed view
  r.toggleAllChecked = await page.locator('#toggle-all').isChecked();
  await page.getByRole('link', { name: 'All' }).click();
  r.allUrl = page.url();
  // direct nav to hash
  await page.goto('https://demo.playwright.dev/todomvc/#/active');
  r.directNavTitles = await page.locator('[data-testid="todo-title"]').allTextContents();
  r.directNavSelected = await page.locator('.filters a.selected').textContent();
  // bogus hash
  await page.goto('https://demo.playwright.dev/todomvc/#/bogus');
  r.bogusTitles = await page.locator('[data-testid="todo-title"]').allTextContents();
  r.bogusSelected = await page.locator('.filters a.selected').count();
  await page.goto('https://demo.playwright.dev/todomvc/#/');
  return r;
}

