async (page) => {
  const r = {};
  const item = page.locator('[data-testid="todo-item"]').nth(1);
  await item.dblclick();
  r.liClassOnEdit = await item.getAttribute('class');
  const edit = item.locator('.edit');
  r.editFocused = await edit.evaluate(e => e === document.activeElement);
  r.editValue = await edit.inputValue();
  // check selection range
  r.selection = await edit.evaluate(e => [e.selectionStart, e.selectionEnd]);
  // edit and enter
  await edit.fill('spaced todo edited');
  await edit.press('Enter');
  r.afterEnter = await page.locator('[data-testid="todo-title"]').allTextContents();
  r.liClassAfter = await item.getAttribute('class');
  // Escape cancels
  await item.dblclick();
  await item.locator('.edit').fill('SHOULD NOT SAVE');
  await item.locator('.edit').press('Escape');
  r.afterEscape = await page.locator('[data-testid="todo-title"]').allTextContents();
  r.liClassAfterEsc = await item.getAttribute('class');
  return r;
}

