async (page) => {
  const r = {};
  await page.evaluate(() => localStorage.clear());
  await page.goto('https://demo.playwright.dev/todomvc/#/');
  const input = page.locator('.new-todo');
  r.mainVisibleEmpty = await page.locator('section.main').isVisible().catch(()=>false);
  r.footerVisibleEmpty = await page.locator('footer.footer').isVisible().catch(()=>false);
  r.mainCountEmpty = await page.locator('section.main').count();
  r.footerCountEmpty = await page.locator('footer.footer').count();
  for (const t of ['a','b','c']) { await input.fill(t); await input.press('Enter'); }
  const items = page.locator('[data-testid="todo-item"]');
  // toggle all
  await page.locator('#toggle-all').check();
  r.classes = await items.evaluateAll(els => els.map(e => e.className));
  r.counter = await page.locator('[data-testid="todo-count"]').textContent();
  r.toggleAllChecked = await page.locator('#toggle-all').isChecked();
  // uncheck toggle all
  await page.locator('#toggle-all').uncheck();
  r.classesAfterUncheck = await items.evaluateAll(els => els.map(e => e.className));
  r.counter2 = await page.locator('[data-testid="todo-count"]').textContent();
  // check individual all -> does toggle-all become checked?
  for (let i=0;i<3;i++) await items.nth(i).locator('.toggle').check();
  r.toggleAllAutoChecked = await page.locator('#toggle-all').isChecked();
  // uncheck one
  await items.nth(1).locator('.toggle').uncheck();
  r.toggleAllAfterOneUnchecked = await page.locator('#toggle-all').isChecked();
  return r;
}

