  await page.reload();
  const input = page.locator('.new-todo');
  await input.fill('one'); await input.press('Enter');
  const item = page.locator('[data-testid="todo-item"]').first();
  const d = item.locator('.destroy');
  const r = {};
  r.visibleNoHover = await d.isVisible();
  r.styleNoHover = await d.evaluate(e => { const s = getComputedStyle(e); return {display:s.display, opacity:s.opacity, visibility:s.visibility}; });
  await item.hover();
  r.visibleHover = await d.isVisible();
  r.styleHover = await d.evaluate(e => { const s = getComputedStyle(e); return {display:s.display, opacity:s.opacity}; });
  return r;
}

